        (bool ok, bytes memory data) = address(c).staticcall(
            abi.encodeWithSignature("getAssertionPolicy(bytes32)", assertionId)
        );
        require(ok, "getAssertionPolicy must not revert");
        assert(data.length == 128);
        uint256 word0;
        uint256 word1;
        uint256 word2;
        uint256 word3;
        assembly {
            word0 := mload(add(data, 32))
            word1 := mload(add(data, 64))
            word2 := mload(add(data, 96))
            word3 := mload(add(data, 128))
        }
        assert(word0 == 0 && word1 == 0 && word2 == 0 && word3 == 0);
    }

    receive() external payable {}
}

