contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 assertionId, bool assertedTruthfully, address caller) public {
        // Precondition: avoid duplicating the contract's own implementation.
        require(true);

        bool reverted;
        if (caller == address(c.optimisticAsserter())) {
            try c.assertionResolvedCallback(assertionId, assertedTruthfully) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.assertionResolvedCallback(assertionId, assertedTruthfully) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // General rule: only the immutable optimistic asserter address is allowed,
        // and all other callers are rejected with a revert.
        assert(caller == address(c.optimisticAsserter()) ? !reverted : reverted);
    }

    receive() external payable {}
}

