contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 assertionId, string memory allowedDisputers, address disputeCaller) public payable {
        c.setDisputeDisputerWhitelist(assertionId, allowedDisputers);
        bool allowed = c.isDisputeAllowed(assertionId, disputeCaller);
        bool expected = _addrInLines(allowedDisputers, disputeCaller);
        assert(allowed == expected);
    }

    function _addrInLines(string memory lines, address disputeCaller) internal pure returns (bool) {
        bytes memory b = bytes(lines);
        uint256 lineStart = 0;
        for (uint256 i = 0; i <= b.length; i++) {
            if (i == b.length || b[i] == 0x0a) {
                if (_lineEqualsAddress(b, lineStart, i, disputeCaller)) {
                    return true;
                }
                lineStart = i + 1;
            }
        }
        return false;
    }

    function _lineEqualsAddress(bytes memory b, uint256 start, uint256 end, address disputeCaller) internal pure returns (bool) {
        if (end - start != 42) {
            return false;
        }
        if (b[start] != 0x30 || b[start + 1] != 0x78) {
            return false;
        }
        uint160 parsed = 0;
        for (uint256 i = start + 2; i < end; i++) {
            uint8 v = _hexVal(b[i]);
            if (v > 15) {
                return false;
            }
            parsed = (parsed << 4) | uint160(v);
        }
        return address(parsed) == disputeCaller;
    }

    function _hexVal(bytes1 ch) internal pure returns (uint8) {
        uint8 c0 = uint8(ch);
        if (c0 >= 48 && c0 <= 57) return c0 - 48;
        if (c0 >= 97 && c0 <= 102) return c0 - 87;
        if (c0 >= 65 && c0 <= 70) return c0 - 55;
        return 255;
    }

    receive() external payable {}
}

